              </div>
              <div>
                <p className="text-sm text-slate-600">Incidencias</p>
                <p className="text-2xl font-bold">
                  {registros.filter(r => r.estado === 'Incidencia' || r.estado === 'Alerta').length}
                </p>
              </div>
